(6370,(select id from categories where slug='przepisy-ogolne'),'W jaki sposób powinieneś obserwować drogę podczas jazdy w ruchu miejskim?','specialist','Tak, aby uzyskać szerokie pole widzenia.','Skupiając się na wąskiej przestrzeni bezpośrednio przed pojazdem.','Nie zwracając uwagi na sytuację za pojazdem.','A','2B315.jpg',2,'KATALOG 07/2026'),
